using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;
using NUnit.Framework;
using Unite.Text.Fonts;
using Unite.Text.Shaping;

namespace Unite.Text.Tests
{
    /// <summary>
    /// Compares the shaper with HarfBuzz on fonts that ship with Windows
    /// (Data/ShapingExpectations.txt, generated by Tools~/GenerateShapingExpectations.py).
    /// Cases whose font is missing are skipped.
    /// </summary>
    public class ShapingConformanceTests
    {
        private const string FontDirectory = "C:/Windows/Fonts/";

        // Allowed difference in font units (anchor rounding, variation interpolation).
        private const float Tolerance = 1.5f;

        [Test]
        public void ShapingMatchesHarfBuzz()
        {
            var faces = new Dictionary<string, FontFace>();
            var analyzer = new TextAnalyzer();
            int cases = 0;
            var failures = new List<string>();

            foreach (string line in File.ReadLines(Path.Combine(UnicodeTests.DataDirectory, "ShapingExpectations.txt")))
            {
                if (line.Length == 0 || line[0] == '#')
                    continue;

                string[] fields = line.Split('\t');
                string fontPath = FontDirectory + fields[0];
                if (!File.Exists(fontPath))
                    continue;

                if (!faces.TryGetValue(fontPath, out var face))
                {
                    face = FontFace.LoadFont(fontPath, fields[0]);
                    faces.Add(fontPath, face);
                }

                var font = InstanceFor(face, fields[1]);
                var direction = fields[2] == "rtl" ? TextDirectionMode.Rtl : TextDirectionMode.Ltr;
                string text = Decode(fields[4]);
                cases++;

                var analysis = new TextAnalysis();
                analyzer.Analyze(analysis, text, direction);
                var shaped = new ShapedText();
                analyzer.Shape(shaped, analysis, font);

                string actual = Describe(shaped, font);
                string expected = fields[5];
                if (!Matches(NormalizeClusters(expected, text), actual))
                    failures.Add($"{fields[0]} [{fields[1]}] {fields[2]} {fields[3]} \"{text}\"\n  expected {expected}\n  actual   {actual}");
            }

            if (cases == 0)
                Assert.Ignore("None of the Windows fonts used by the expectations are installed.");
            Assert.IsEmpty(failures, $"{failures.Count} of {cases} cases differ from HarfBuzz:\n" + string.Join("\n", failures));
        }

        private static FontInstance InstanceFor(FontFace face, string variations)
        {
            if (string.IsNullOrEmpty(variations))
                return face.Default;

            var settings = new List<AxisSetting>();
            foreach (string item in variations.Split(','))
            {
                string[] pair = item.Split('=');
                settings.Add(new AxisSetting(pair[0], float.Parse(pair[1], CultureInfo.InvariantCulture)));
            }
            return face.GetInstance(settings);
        }

        private static string Decode(string codePoints)
        {
            var text = new StringBuilder();
            foreach (string token in codePoints.Split(' ', StringSplitOptions.RemoveEmptyEntries))
                text.Append(char.ConvertFromUtf32(int.Parse(token, NumberStyles.HexNumber)));
            return text.ToString();
        }

        private static string Describe(ShapedText shaped, FontInstance font)
        {
            var result = new StringBuilder();
            float units = font.UnitsPerEm;
            for (int index = 0; index < shaped.GlyphCount; index++)
            {
                var glyph = shaped.Glyphs[index];
                if (result.Length > 0)
                    result.Append(' ');
                result.Append(FormattableString.Invariant(
                    $"{glyph.GlyphId}:{glyph.Cluster}:{glyph.Advance * units:0.#}:{glyph.OffsetX * units:0.#}:{glyph.OffsetY * units:0.#}"));
            }
            return result.ToString();
        }

        // HarfBuzz gives a removed default ignorable's cluster to the next glyph; Unite.Text
        // keeps such characters inside the cluster before them. Move those cluster values
        // to the next visible character so the comparison is about glyphs.
        private static string NormalizeClusters(string expected, string text)
        {
            var codePoints = new List<int>();
            for (int index = 0; index < text.Length; index += char.IsSurrogatePair(text, index) ? 2 : 1)
                codePoints.Add(char.ConvertToUtf32(text, index));

            string[] glyphs = expected.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            for (int index = 0; index < glyphs.Length; index++)
            {
                string[] fields = glyphs[index].Split(':');
                int cluster = int.Parse(fields[1]);
                while (cluster < codePoints.Count - 1 && Unicode.UnicodeData.IsDefaultIgnorable(codePoints[cluster]))
                    cluster++;
                fields[1] = cluster.ToString(CultureInfo.InvariantCulture);
                glyphs[index] = string.Join(":", fields);
            }
            return string.Join(" ", glyphs);
        }

        private static bool Matches(string expected, string actual)
        {
            string[] left = expected.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            string[] right = actual.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            if (left.Length != right.Length)
                return false;

            for (int index = 0; index < left.Length; index++)
            {
                string[] a = left[index].Split(':');
                string[] b = right[index].Split(':');
                if (a[0] != b[0] || a[1] != b[1])
                    return false;
                for (int field = 2; field < 5; field++)
                {
                    float x = float.Parse(a[field], CultureInfo.InvariantCulture);
                    float y = float.Parse(b[field], CultureInfo.InvariantCulture);
                    if (Math.Abs(x - y) > Tolerance)
                        return false;
                }
            }
            return true;
        }
    }
}
